-- race indicator dump
SET NAMES utf8mb4;
START TRANSACTION;
DROP TABLE IF EXISTS `indicator_category`;
CREATE TABLE `indicator_category` (
  `code` varchar(16) NOT NULL,
  `name` varchar(64) NOT NULL,
  `level` varchar(8) NOT NULL,
  `parent_code` varchar(16) DEFAULT NULL,
  `display_order` int NOT NULL,
  PRIMARY KEY (`code`),
  KEY `ix_indicator_category_parent_code` (`parent_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DELETE FROM `indicator_category`;
DROP TABLE IF EXISTS `indicator_config`;
CREATE TABLE `indicator_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(32) NOT NULL,
  `name` varchar(128) NOT NULL,
  `level` varchar(8) NOT NULL,
  `category_code` varchar(16) NOT NULL,
  `category_name` varchar(64) NOT NULL,
  `indicator_type` varchar(8) NOT NULL,
  `unit` varchar(32) NOT NULL,
  `value_range` varchar(255) NOT NULL,
  `data_source` varchar(255) NOT NULL,
  `is_feature` tinyint(1) NOT NULL,
  `risk_meaning` varchar(255) NOT NULL,
  `weight_star` float NOT NULL,
  `region` varchar(64) NOT NULL,
  `is_veto` tinyint(1) NOT NULL,
  `cycle` varchar(8) NOT NULL,
  `scoring_rule` varchar(255) NOT NULL,
  `display_order` int NOT NULL,
  `scoring_config` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_indicator_config_code` (`code`),
  KEY `ix_indicator_config_name` (`name`),
  KEY `ix_indicator_config_level` (`level`),
  KEY `ix_indicator_config_category_code` (`category_code`)
) ENGINE=InnoDB AUTO_INCREMENT=776 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DELETE FROM `indicator_config`;
DROP TABLE IF EXISTS `data_source_mapping`;
CREATE TABLE `data_source_mapping` (
  `id` int NOT NULL AUTO_INCREMENT,
  `data_source` varchar(32) NOT NULL,
  `data_field` varchar(64) NOT NULL,
  `indicator_code` varchar(32) NOT NULL,
  `transform_rule` varchar(255) NOT NULL,
  `aggregation` varchar(16) NOT NULL,
  `reliability` float NOT NULL,
  `conflict_policy` varchar(32) NOT NULL,
  `active` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_data_source_mapping_indicator_code` (`indicator_code`),
  KEY `ix_data_source_mapping_data_source` (`data_source`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DELETE FROM `data_source_mapping`;
DROP TABLE IF EXISTS `business_type_config`;
CREATE TABLE `business_type_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `business_type_code` varchar(16) NOT NULL,
  `name` varchar(64) NOT NULL,
  `level_weights` json NOT NULL,
  `feature_boost` float NOT NULL,
  `region_boost` json NOT NULL,
  `synergy_factors` json NOT NULL,
  `active` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_business_type_config_business_type_code` (`business_type_code`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DELETE FROM `business_type_config`;
COMMIT;